/** Prints the card list as Markdown, straight from the card data. Usage: npm run cards */
import { CARDS } from "../src/content/factions.ts";
import type { Card } from "../src/engine/index.ts";

const stats = (c: Card) =>
  c.kind === "unit" || c.kind === "structure"
    ? `${c.attack}/${c.health}, range ${c.range}${c.kind === "unit" ? `, move ${c.move}` : ""}`
    : "";
const out = [
  "# Card list",
  "",
  "Generated by `npm run cards` from `src/content/factions.ts`. Names are placeholders until the setting pass (D-011).",
];
for (const faction of ["ironbound", "verdant"]) {
  out.push("", `## ${faction[0]!.toUpperCase()}${faction.slice(1)}`, "");
  for (const c of Object.values(CARDS).filter((x) => x.faction === faction)) {
    const bits = [`cost ${c.cost}`, c.kind, stats(c), c.text ?? ""].filter(Boolean);
    out.push(`- **${c.name}**: ${bits.join(" · ")}`);
  }
}
console.log(out.join("\n"));
